import React from "react";
import { graphql } from "gatsby";
import { useTranslation } from "gatsby-plugin-react-i18next";
import Layout from "../components/Layout";
import { Post, Company } from "../interfaces";
import data from "../data/data.json";
import { format, isValid, parseISO } from "date-fns";
import { es, fr, enUS, sl } from "date-fns/locale";
import images from "../images";
import AppLink from "../components/AppLink";

const info: Company = data[0];

type Props = {
  data: {
    allPostsJson: {
      nodes: Post[];
    };
  };
};

const PostPage: React.FC<Props> = ({ data }) => {
  const posts = data.allPostsJson.nodes;

  const { t, i18n } = useTranslation("blog");
  const [searchTerm, setSearchTerm] = React.useState("");
  const [yearFilter, setYearFilter] = React.useState("all");
  const getLocale = (language: string) => {
    switch (language) {
      case "es":
        return es;
      case "fr":
        return fr;
      default:
        return enUS;
    }
  };

  const getPostTimestamp = (value?: string | null) => {
    if (!value) {
      return null;
    }

    const parsed = parseISO(value);
    return isValid(parsed) ? parsed.getTime() : null;
  };

  const sortedPosts = React.useMemo(
    () =>
      [...posts].sort((a, b) => {
        const aTime = getPostTimestamp(a.date);
        const bTime = getPostTimestamp(b.date);

        if (aTime === null && bTime === null) {
          return 0;
        }

        if (aTime === null) {
          return 1;
        }

        if (bTime === null) {
          return -1;
        }

        return bTime - aTime;
      }),
    [posts]
  );

  const availableYears = React.useMemo(() => {
    const years = new Set<number>();
    sortedPosts.forEach((post) => {
      const time = getPostTimestamp(post.date);
      if (time !== null) {
        years.add(new Date(time).getFullYear());
      }
    });
    return Array.from(years).sort((a, b) => a - b);
  }, [sortedPosts]);

  const normalizedQuery = searchTerm.trim().toLowerCase();

  const filteredPosts = React.useMemo(() => {
    return sortedPosts.filter((post) => {
      const postTime = getPostTimestamp(post.date);
      const postYear =
        postTime === null ? null : new Date(postTime).getFullYear().toString();
      if (yearFilter !== "all") {
        if (postYear === null || postYear !== yearFilter) {
          return false;
        }
      }

      if (!normalizedQuery) {
        return true;
      }

      const translatedTitle = t(`blog.${post.slug}-title`, {
        defaultValue: post.title,
      });

      return (
        translatedTitle.toLowerCase().includes(normalizedQuery) ||
        post.title.toLowerCase().includes(normalizedQuery)
      );
    });
  }, [normalizedQuery, sortedPosts, t, yearFilter, i18n.language]);

  const searchLabel = t("blog.search_label", {
    defaultValue: "Search",
  });
  const searchPlaceholder = t("blog.search_placeholder", {
    defaultValue: "Search posts by title",
  });
  const filterLabel = t("blog.filter_label", {
    defaultValue: "Filter by year",
  });
  const filterAll = t("blog.filter_all", {
    defaultValue: "All years",
  });
  const noResults = t("blog.no_results", {
    defaultValue: "No posts match your search.",
  });

  return (
    <Layout data={info}>
      <article className="w-full sm:w-3/4 mx-auto mb-4">
        <h1 className="text-3xl text-center my-4">{t("blog.title")}</h1>
        <div className="flex flex-col sm:flex-row gap-3 mb-4">
          <label className="flex-1 text-sm text-secondary">
            <span className="block mb-1">{searchLabel}</span>
            <input
              className="w-full rounded-lg border-2 border-secondary/40 bg-darkBg/50 px-3 py-2 text-white focus:outline-none focus:ring-2 focus:ring-secondary/60"
              type="search"
              value={searchTerm}
              onChange={(event) => setSearchTerm(event.target.value)}
              placeholder={searchPlaceholder}
              aria-label={searchLabel}
            />
          </label>
          <label className="sm:w-48 text-sm text-secondary">
            <span className="block mb-1">{filterLabel}</span>
            <select
              className="w-full rounded-lg border-2 border-secondary/40 bg-darkBg/50 px-3 py-2 text-white focus:outline-none focus:ring-2 focus:ring-secondary/60"
              value={yearFilter}
              onChange={(event) => setYearFilter(event.target.value)}
              aria-label={filterLabel}
            >
              <option value="all">{filterAll}</option>
              {availableYears.map((year) => (
                <option key={year} value={year}>
                  {year}
                </option>
              ))}
            </select>
          </label>
        </div>
        {filteredPosts.length === 0 ? (
          <p className="text-center text-secondary">{noResults}</p>
        ) : (
          <ul className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
            {filteredPosts.map((post) => (
              <li
                className="text-center border-2 bg-darkBg/50 rounded-lg p-2 flex-1 flex flex-col"
                key={post.slug}
              >
                <AppLink to={`/blog/${post.slug}`}>
                  <h2>{t(`blog.${post.slug}-title`)}</h2>
                  <p className="text-sm text-secondary">
                    {(() => {
                      const parsed = parseISO(post.date);
                      return isValid(parsed)
                        ? format(parsed, "MMMM dd, yyyy", {
                            locale: getLocale(i18n.language),
                          })
                        : post.date;
                    })()}
                  </p>
                  <img
                    className="thumbnail mx-auto my-4"
                    src={images[post.slug as keyof typeof images].src}
                    alt={images[post.slug as keyof typeof images].alt}
                  />
                </AppLink>
              </li>
            ))}
          </ul>
        )}
      </article>

    </Layout>
  );
};

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
    allPostsJson(sort: { date: DESC }) {
      nodes {
        title
        slug
        date
      }
    }
  }
`;

export default PostPage;
